            QScrollBar:vertical {
                background: transparent;
                width: 10px;
                margin: 0px;
            }
            QScrollBar::handle:vertical {
                background: #d0d0d0;
                border-radius: 5px;
                min-height: 30px;
                margin: 2px;
            }
            QScrollBar::handle:vertical:hover {
                background: #b0b0b0;
            }
            QScrollBar:horizontal {
                background: transparent;
                height: 10px;
                margin: 0px;
            }
            QScrollBar::handle:horizontal {
                background: #d0d0d0;
                border-radius: 5px;
                min-width: 30px;
                margin: 2px;
            }
            QScrollBar::handle:horizontal:hover {
                background: #b0b0b0;
            }
            QScrollBar::add-line, QScrollBar::sub-line {
                background: none;
                border: none;
            }

            /* Sidebar dock widget styling */
            QDockWidget {
                border: none;
                background: #ffffff;
            }
            QDockWidget::title {
                background: #f8f9fa;
                padding: 10px 15px;
                border-bottom: 1px solid #eaeaea;
                font-weight: 600;
                color: #333;
            }

